css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; }
.loader span { position: absolute; width: 44%; height: 44%; border-radius: 12%; border: calc(var(--loader-size) * .012) solid color-mix(in srgb, #fff 30%, transparent); opacity: 0; animation: drop calc(var(--loader-speed) * 2) ease-in infinite; }
.loader span:nth-child(1) { left: 4%; top: 4%; background: var(--accent); animation-delay: 0s; }
.loader span:nth-child(2) { right: 4%; top: 4%; background: var(--accent-2); animation-delay: calc(var(--loader-speed) * .3); }
.loader span:nth-child(3) { left: 4%; bottom: 4%; background: var(--accent-2); animation-delay: calc(var(--loader-speed) * .6); }
.loader span:nth-child(4) { right: 4%; bottom: 4%; background: var(--accent); animation-delay: calc(var(--loader-speed) * .9); }
@keyframes drop { 0% { transform: translateY(-130%); opacity: 0; } 12% { opacity: 1; } 32%, 88% { transform: translateY(0); opacity: 1; } 100% { transform: translateY(0); opacity: 0; } }
